package connector

import (
	"strings"
	"testing"
)

// TestGeneratedMinifiedSniff pins LB-F10 (docs/design/language-breadth.md
// §5): a `@generated` / `Code generated … DO NOT EDIT` marker in a comment
// in the first 2 KiB, or an average line length over 500 in the first
// 64 KiB, fingerprints the file as skipped_generated.
func TestGeneratedMinifiedSniff(t *testing.T) {
	longLine := strings.Repeat("a=1;", 200) // 800 chars
	cases := []struct {
		name    string
		path    string
		content string
		want    bool
	}{
		{"empty", "a.js", "", false},
		{"plain js", "a.js", "function f() {\n  return 1\n}\n", false},
		{"go convention", "a.go", "// Code generated by protoc-gen-go. DO NOT EDIT.\n\npackage x\n", true},
		{"at-generated jsdoc", "a.ts", "/**\n * @generated\n */\nexport const x = 1\n", true},
		{"at-generated hash comment", "a.py", "# @generated by tool\ndef f(): pass\n", true},
		{"at-generated after 2KiB", "a.py", strings.Repeat("x = 1\n", 400) + "# @generated\n", false},
		{"at-generated in a string is not a marker", "a.py", "s = '@generated'\n", false},
		{"marker in first 2KiB past line 3", "a.rb", "# a\n# b\n# c\n# d\n# Code generated by x. DO NOT EDIT.\n", true},
		{"json never marker-flagged", "a.json", "{\"note\": \"@generated\"}\n", false},
		{"minified single line", "a.min.js", longLine, true},
		{"minified many long lines", "a.js", strings.Repeat(longLine+"\n", 20), true},
		{"long but average short", "a.js", longLine + "\n" + strings.Repeat("x\n", 100), false},
		{"exactly 500 average is not over", "a.js", strings.Repeat("b", 499) + "\n", false},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			if got := IsGeneratedOrMinified(c.path, []byte(c.content)); got != c.want {
				t.Fatalf("IsGeneratedOrMinified(%q) = %v, want %v", c.path, got, c.want)
			}
		})
	}
}

// TestGeneratedMinifiedSniff_ScansOnly64KiB: the average is over the first
// 64 KiB, so a minified tail after a normal head does not flag the file and
// a normal tail after a minified head does.
func TestGeneratedMinifiedSniff_ScansOnly64KiB(t *testing.T) {
	normal := strings.Repeat("x = 1\n", (70<<10)/6)
	minified := strings.Repeat("m", 70<<10)
	if IsGeneratedOrMinified("a.js", []byte(normal+minified)) {
		t.Fatal("minified tail past 64 KiB flagged the file")
	}
	if !IsGeneratedOrMinified("a.js", []byte(minified+"\n"+normal)) {
		t.Fatal("minified 64 KiB head not flagged")
	}
}
